llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C33"],
      "claim": "Record C33 reports an absolute oral bioavailability of 0.43 ± 0.14 for nifedipine after a 30 mg oral tablet dose, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Record C21 reports an absolute oral bioavailability of 35% for rigosertib in fasting patients at 560 mg, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Record C18 reports an absolute oral bioavailability of 16% for isradipine in healthy volunteers, below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most high-transfer evidence molecules show direct absolute oral bioavailability values above 20% (e.g., 43%, 35%, 50%, 90%), while two molecules show values below 20% (16%, 18%). The preponderance of ordinary-condition absolute measurements supports high bioavailability, with moderate confidence due to conflicting low values.",
  "evidence_gaps": [
    "Molecule 6 combines records for different compounds (ORH-2014 and TSU-68), so its evidence is discounted.",
    "Molecule 4 provides only qualitative 'good' bioavailability without a numeric threshold-relevant value.",
    "Molecule 2 has one outlier record (C41, 28%) conflicting with multiple 16-19% values; classified as low based on repeated ordinary-condition measurements."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

